package com.sabyeguyz.clinic.commission;
import com.sabyeguyz.clinic.course.CoursePurchase; import com.sabyeguyz.clinic.staff.Staff; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate;
@Entity @Table(name="treatment_fee_rules") public class TreatmentFeeRule { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="employee_id") private Staff employee; @Column(name="fee_type") private String feeType; @Column(name="fee_value") private BigDecimal feeValue; @Column(name="percentage_base") private String percentageBase; @Column(name="effective_from") private LocalDate effectiveFrom; @Column(name="effective_to") private LocalDate effectiveTo; private boolean active=true; protected TreatmentFeeRule(){} public TreatmentFeeRule(Staff e,String t,BigDecimal v,String b,LocalDate f,LocalDate to){employee=e;feeType=t;feeValue=v;percentageBase=b;effectiveFrom=f;effectiveTo=to;} public BigDecimal calculate(CoursePurchase p){return "PERCENTAGE".equals(feeType)?p.getPrice().divide(BigDecimal.valueOf(p.totalSessions()),2,java.math.RoundingMode.HALF_UP).multiply(feeValue).divide(BigDecimal.valueOf(100),2,java.math.RoundingMode.HALF_UP):feeValue;} public void deactivate(){active=false;} public Long getId(){return id;} public Staff getEmployee(){return employee;} public String getFeeType(){return feeType;} public BigDecimal getFeeValue(){return feeValue;} public String getPercentageBase(){return percentageBase;} public LocalDate getEffectiveFrom(){return effectiveFrom;} public LocalDate getEffectiveTo(){return effectiveTo;} public boolean isActive(){return active;}}
